            const carCanopy = new THREE.Group();
            carCanopy.position.y = 0.38;
            car.add(carCanopy);
            put(edge(new THREE.ConeGeometry(0.11, 0.07, 10)), 0, 0.035, 0, 0, 0, 0, carCanopy);
            const carStars = [];
